package dev.shusenzheng64.courseaxis.data
import dev.shusenzheng64.courseaxis.core.MergeEngine
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URI
import java.net.URL
sealed interface SyncResult{data class Success(val revision:Long,val message:String):SyncResult;data class Failure(val message:String):SyncResult}
class SyncClient(private val repository:ScheduleRepository,private val settings:SyncSettings){
    suspend fun pull():SyncResult=try{val c=config();val response=withContext(Dispatchers.IO){request("GET","${c.serverUrl}/v1/document",c.token,null)};if(response.code !in 200..299)error("服务器返回 ${response.code}: ${response.body}");val root=JSONObject(response.body);val rev=root.getLong("revision");val remote=root.optJSONObject("document")?.let{ScheduleJsonCodec.decode(it.toString())};if(remote!=null)repository.replace(MergeEngine.merge(repository.document.value,remote));settings.setRevision(rev);SyncResult.Success(rev,if(remote==null)"服务器尚无数据" else "已拉取并合并")}catch(e:Throwable){SyncResult.Failure(e.message?:"同步失败")}
    suspend fun push():SyncResult=try{var c=config();var document=repository.document.value;repeat(2){attempt->val payload=JSONObject().apply{put("baseRevision",c.revision);put("document",ScheduleJsonCodec.toJson(document))}.toString();val response=withContext(Dispatchers.IO){request("PUT","${c.serverUrl}/v1/document",c.token,payload)};if(response.code in 200..299){val rev=JSONObject(response.body).getLong("revision");settings.setRevision(rev);return SyncResult.Success(rev,"已上传")};if(response.code!=409||attempt==1)error("服务器返回 ${response.code}: ${response.body}");val pulled=withContext(Dispatchers.IO){request("GET","${c.serverUrl}/v1/document",c.token,null)};if(pulled.code !in 200..299)error("冲突处理失败：${pulled.code}");val root=JSONObject(pulled.body);val remote=root.optJSONObject("document")?.let{ScheduleJsonCodec.decode(it.toString())};val rev=root.getLong("revision");if(remote!=null){document=MergeEngine.merge(document,remote);repository.replace(document)};settings.setRevision(rev);c=settings.load()};error("同步重试失败")}catch(e:Throwable){SyncResult.Failure(e.message?:"同步失败")}
    private fun config():SyncConfiguration{val c=settings.load();val uri=runCatching{URI(c.serverUrl)}.getOrNull()?:error("同步地址无效");val local=uri.host in setOf("127.0.0.1","localhost","::1")||uri.host?.startsWith("10.")==true||uri.host?.startsWith("192.168.")==true||uri.host?.let{h->h.startsWith("172.")&&h.split('.').getOrNull(1)?.toIntOrNull() in 16..31}==true;require(uri.scheme=="https"||(uri.scheme=="http"&&local)){"请使用 HTTPS；局域网测试可使用私有地址"};require(c.token.length>=24){"同步令牌至少 24 字符"};return c}
    private fun request(method:String,url:String,token:String,body:String?):HttpResponse{val conn=(URL(url).openConnection() as HttpURLConnection).apply{requestMethod=method;connectTimeout=10000;readTimeout=15000;setRequestProperty("Authorization","Bearer $token");setRequestProperty("Accept","application/json");if(body!=null){doOutput=true;setRequestProperty("Content-Type","application/json; charset=utf-8");outputStream.use{it.write(body.toByteArray())}}};return try{val code=conn.responseCode;val stream=if(code>=400)conn.errorStream else conn.inputStream;HttpResponse(code,stream?.bufferedReader()?.use{it.readText()}.orEmpty())}finally{conn.disconnect()}}
    private data class HttpResponse(val code:Int,val body:String)
}
